\lstset{language=C}
\begin{lstlisting}
while (i < k) {
 tmp = a[i];
 a[i] = a[i+1];
 a[i+1] = tmp;
 i = i + 1;
}
\end{lstlisting}

\begin{align*}
& \textbf{while}\ (i < k)\ \{ \\
& \qquad
 \begin{pmatrix} 
 a[i] \\ 
 a[i+1] \\ 
 i
 \end{pmatrix}
 \gets
 \begin{pmatrix} 
 a[i+1] \\ 
 a[i] \\ 
 i+1
 \end{pmatrix}\\
& \}
\end{align*}

\lstset{language=C}
\begin{lstlisting}
while (i < k) {
 i = i + 1;
}
\end{lstlisting}

\[
 \begin{pmatrix} 
 a[i] \\ 
 a[i+1] \\ 
 i
 \end{pmatrix}
 \gets
 \begin{pmatrix} 
 a[i+1] \\ 
 a[i] \\ 
 i+1
 \end{pmatrix}
\]

\begin{definition}[Array-Solvable]~
\begin{itemize}
\item all lvalues inductive or displacing
\item no ``mixtures'' of both kinds
\item monotonic array indices
\end{itemize}
\end{definition}

\[
\begin{array}{ccc}
 \begin{pmatrix} 
 a[i] \\ 
 a[i+1]
 \end{pmatrix} & {} \gets {} & \begin{pmatrix} 
 a[i+1] \\ 
 a[i]
 \end{pmatrix}\\
 \begin{pmatrix} 
 i^{(n)}
 \end{pmatrix} & {} = {} &
 \begin{pmatrix} 
 i^{(0)}+n
 \end{pmatrix}
\end{array}
\]

\lstset{language=C}
\begin{lstlisting}[escapechar=@]
int tmp;
unsigned i = 0;
int fst = a[0];
while (i < k) {
 tmp = a[i];
 a[i] = a[i+1];
 a[i+1] = tmp;
 i = i + 1;
}
assert(fst @==@ a[k]);
\end{lstlisting}

\begin{itemize}
 \item $\lambda$s?!?!
 \begin{itemize}
 \item Lemmas on demand! [Preiner, Niemetz, Biere]
 \end{itemize}
 \item multi-dimensional?
 \begin{itemize}
 \item arrays are functions
 \item $d$-dimensional arrays are functions of arity $d$
 \item $0$-dimensional arrays are scalars
 \item \textbf{Uniform Acceleration!}
 \end{itemize}
\end{itemize}

\[
\begin{array}{ccc}
 \begin{pmatrix} 
 a[i]
 \end{pmatrix} & {} \gets {} & \begin{pmatrix} 
 a[i+1]
 \end{pmatrix}\\
 \begin{pmatrix}
 a[i]^{(n)} \\
 i^{(n)}
 \end{pmatrix} & {} = {} &
 \begin{pmatrix} 
 a[i]^{(0)} \\
 i^{(0)}+n
 \end{pmatrix}
\end{array}
\]

\[
\begin{array}{ccc}
 \begin{pmatrix}
 a[i+1]^{(n)} \\
 a[i]^{(n)} \\
 i^{(n)}
 \end{pmatrix} & {} = {} &
 \begin{pmatrix}
 a^{(0)}[i^{(n)}+1] \\
 a[i]^{(0)} \\
 i^{(0)}+n
 \end{pmatrix}
\end{array}
\]
